def truncate_words(text: str, limit: int) -> str:
    if limit < 1:
        raise ValueError("limit must be at least 1")

    if len(text) <= limit:
        return text

    max_prefix_len = limit - 1

    # Check if we can include text[:max_prefix_len] and it ends at a word boundary
    if text[max_prefix_len].isspace():
        prefix = text[:max_prefix_len].rstrip()
        return prefix + "…"

    # Find the last whitespace in text[:max_prefix_len]
    prefix = text[:max_prefix_len]
    for i in range(len(prefix) - 1, -1, -1):
        if prefix[i].isspace():
            prefix = prefix[:i].rstrip()
            return prefix + "…"

    # No whitespace found, first word is too long
    return text[:max_prefix_len] + "…"
